INSERT INTO goals (id,code,name,description,display_order,is_active,level_domain_id) VALUES
 ('GL100001','VB.1.1','Phát ra 2 yêu cầu bằng âm thanh, ra dấu hiệu hoặc PECS, có thể nhắc bằng lời (không nhắc thể chất) (E)',NULL,1,1,'LD5001'),
 ('GL100002','VB.1.2','Đưa ra 4 yêu cầu khác nhau không nhắc nhở ngoại trừ gợi ý "con muốn gì?" - các mong muốn có thể có sẵn (T)',NULL,2,1,'LD5001'),
 ('GL100003','VB.1.3','Khái quát hóa được 6 yêu cầu cho 2 người, 2 bối cảnh, 2 nội dung khác nhau (vd: bố - mẹ, nhà - sân chơi, nước uống - bóng) (E)',NULL,3,1,'LD5001'),
 ('GL100004','VB.1.4','Tự phát ra 5 yêu cầu không nhắc bằng lời - vật mong muốn có thể có sẵn (TO 60 phút)',NULL,4,1,'LD5001'),
 ('GL100005','VB.1.5','Tự phát ra 10 yêu cầu trong mà không cần lời nhắc ngoại trừ "con muốn gì?" - vật mong muốn có thể có sẵn (E)',NULL,5,1,'LD5001'),
 ('GL100006','VB.2.1','Gán tên 2 sự vật như con người, đồ vật, thú cưng, nhân vật (có thể là trong thể hiện yêu cầu) - không có lời nhắc (T)',NULL,1,1,'LD5002'),
 ('GL100007','VB.2.3','Gán tên 6 sự vật không cần động lực hay củng cố - không có lời nhắc (vd: giày, mũ, thìa, ô tô, cốc, giường) (T)',NULL,2,1,'LD5002'),
 ('GL100008','VB.2.4','Tự phát gán tên 2 sự vật khác nhau - không cần nhắc lời (O)',NULL,3,1,'LD5002'),
 ('GL100009','VB.2.5','Gán tên 10 sự vật khác nhau (đồ vật thông thường, con người, bộ phận cơ thể, hình ảnh) (T)',NULL,4,1,'LD5002'),
 ('GL100010','VB.2.2','Gán tên 4 sự vật như con người, đồ vật, thú cưng, nhân vật (có thể là trong thể hiện yêu cầu) - không có lời nhắc (T)',NULL,5,1,'LD5002'),
 ('GL100011','VB.3.1','Chú ý đến giọng nói của người nói bằng cách giao tiếp mắt với người nói 5 lần (E)',NULL,1,1,'LD5003'),
 ('GL100012','VB.3.2','Phản hồi với tên gọi của mình đạt 5 lần (T)',NULL,2,1,'LD5003'),
 ('GL100013','VB.3.3','Đạt 5 lần nhìn, chạm hoặc chỉ đúng vào người thân, thú cưng, vật yêu thích khi được trình bày theo cặp (vd: Mẹ đâu?, A Tôm đâu? khi có 2 người/2 ảnh) (E)',NULL,3,1,'LD5003'),
 ('GL100014','VB.3.4','Thực hiện 4 hành động vận động khác nhau theo lệnh (không nhắc trực quan) vd: Con nhảy lên, vỗ tay nào (T)',NULL,4,1,'LD5003'),
 ('GL100015','VB.3.5','Chọn đúng 1 trong 4, từ 20 vật hoặc hình ảnh khác nhau (vd: Chỉ mèo, chạm vào giầy...) (T)',NULL,5,1,'LD5003'),
 ('GL100016','VB.4.1','Dõi theo vật kích thích di chuyển trong 2s, 5 lần (TO 30 phút)',NULL,1,1,'LD5004'),
 ('GL100017','VB.4.2','Cầm các vật nhỏ bằng ngón cái, ngón trỏ và ngón giữa (gọng kìm) 5 lần (O)',NULL,2,1,'LD5004'),
 ('GL100018','VB.4.3','Dõi theo một món đồ chơi hoặc cuốn sách trong 30s không cần kích thích (O)',NULL,3,1,'LD5004'),
 ('GL100019','VB.4.5','Ghép đôi được 10 sự vật giống nhau (vd: mảnh ghép hình, đồ chơi, đồ vật, tranh ảnh ...) (E)',NULL,4,1,'LD5004'),
 ('GL100020','VB.4.4','Thực hiện được 2 trong 3 hoạt động: Đặt 3 vật vào 1 thùng chứa, xếp chồng 3 khối gỗ, treo 3 vòng vào móc (E)',NULL,5,1,'LD5004'),
 ('GL100021','VB.5.1','Thao tác và khám phá đồ vật trong 1 phút (vd: nhìn đồ chơi, lật đồ chơi, bấm nút, ...) (TO 30 phút)',NULL,1,1,'LD5005'),
 ('GL100022','VB.5.2','Thể hiện sự đa dạng trong cách chơi bằng cách tương tác độc lập với 5 đồ vật khác nhau (vd: chơi vòng, tiếp đó là bóng, sau đó là 1 khối...) (TO 30 phút)',NULL,2,1,'LD5005'),
 ('GL100023','VB.5.3','Thể hiện khả năng khái quát hóa bằng cách tham gia khám phá và chơi với đồ chơi trong môi trường mới lạ 2 phút (vd: phòng chơi mới) (TO 30 phút)',NULL,3,1,'LD5005'),
 ('GL100024','VB.5.4','Độc lập tham gia các trò chơi chuyển động trong 2 phút (vd: đu dây, nhảy múa, lắc lư, leo trèo ...) (TO 30 phút)',NULL,4,1,'LD5005'),
 ('GL100025','VB.5.5','Độc lập tham gia các trò chơi nguyên nhân - kết quả trong vòng 2 phút (vd: thùng chứa đồ, đồ chơi kéo, đồ chơi bật lên...) (TO 30 phút)',NULL,5,1,'LD5005'),
 ('GL100026','VB.6.1','Giao tiếp mắt 5 lần (TO 30 phút)',NULL,1,1,'LD5006'),
 ('GL100027','VB.6.2','Thể hiện trẻ muốn được bế hay chơi đùa 2 lần (vd: trèo lên lòng mẹ) (TO 60 phút)',NULL,2,1,'LD5006'),
 ('GL100028','VB.6.3','Tự nhiên giao tiếp bằng mắt với trẻ khác 5 lần (TO 30 phút)',NULL,3,1,'LD5006'),
 ('GL100029','VB.6.4','Tự phát tham gia chơi song song gần những đứa trẻ khác trong tổng thời gian 2 phút (ví dụ: ngồi trong hộp cát gần những đứa trẻ khác) (TO 30 phút)',NULL,4,1,'LD5006'),
 ('GL100030','VB.6.5','Tự phát đi theo bạn bè hoặc bắt chước hành vi vận động của họ 2 lần (ví dụ: đi theo bạn vào nhà chơi) (TO 30 phút)',NULL,5,1,'LD5006'),
 ('GL100031','VB.7.1','Bắt chước 2 chuyển động vận động thô khi được nhắc làm việc này (ví dụ: vỗ tay, giơ tay) (T)',NULL,1,1,'LD5007'),
