 ('GL100049','VB.1.9','Tự phát đưa ra 15 yêu cầu khác nhau (ít nhất có 2 yêu cầu là động lực) (TO 30 phút)',NULL,4,1,'LD5010'),
 ('GL100050','VB.1.10','Đưa ra 10 yêu cầu mới (có thể đã được hướng dẫn cùng cách thức trước đó) (O)',NULL,5,1,'LD5010'),
 ('GL100051','VB.2.6','Gán tên được 25 sự vật khi được hỏi "Cái gì đây?" (T)',NULL,1,1,'LD5011'),
 ('GL100052','VB.2.7','Khái quát được tên ở 3 mẫu khác nhau của 50 sự vật (xem danh sách phụ lục 1) (T)',NULL,2,1,'LD5011'),
 ('GL100053','VB.2.8','Gán tên được 10 hành động đang diễn ra khi được hỏi "tôi đang làm gì? (vd: Vỗ tay, nhảy, hắt hơi, ngủ, khóc, thổi, khiêu vũ, vẫy tay, ho, gõ cửa) (T)',NULL,3,1,'LD5011'),
 ('GL100054','VB.2.9','Gán tên được 50 cụm từ kết hợp 2 thành phần: Danh từ - động từ hoặc đông từ - danh từ (vd: vỗ tay, mở miệng...) (T)',NULL,4,1,'LD5011'),
 ('GL100055','VB.2.10','Gán tên được 200 danh từ hoặc động từ (xem danh sách phụ lục ) (T)',NULL,5,1,'LD5011'),
 ('GL100056','VB.3.6','Chọn đúng 1 trong 6, từ 40 vật hoặc hình ảnh khác nhau (vd: Chỉ mèo, chạm vào giầy...) (T)',NULL,1,1,'LD5012'),
 ('GL100057','VB.3.7','Khái quát được 3 mẫu khác nhau của 50 sự vật, chọn 1 trong 8 (vd: 3 con mèo khác nhau, 3 xe máy khác nhau...) (T)',NULL,2,1,'LD5012'),
 ('GL100058','VB.3.8','Thực hiện 10 hành động vận động cụ thể theo lệnh (ví dụ: Chỉ cho tôi cách vỗ tay. Bạn có thể nhảy không?) (T)',NULL,3,1,'LD5012'),
 ('GL100059','VB.3.9','Chọn đúng yêu cầu được 50 cụm từ kết hợp 2 thành phần: Danh từ - động từ hoặc đông từ - danh từ (vd: em bé đang ngủ, đẩy xích đu ...) (T)',NULL,4,1,'LD5012'),
 ('GL100060','VB.3.10','Chọn đúng mục trong sách, tranh hoặc môi trường tự nhiên khi được gọi tên cho 250 từ (tích lũy từ các phần đã biết và/hoặc đã kiểm tra) (T)',NULL,5,1,'LD5012'),
 ('GL100061','VB.4.6','Ghép đôi được 25 sự vật giống hệt nhau trong mảng lộn xộn 6 đối tượng (T)',NULL,1,1,'LD5013'),
 ('GL100062','VB.4.7','Sắp xếp các sự vật khác nhau theo 10 màu sắc (vd: bát xanh dương, bát đỏ, gấu đỏ, gấu vàng, ô tô cam, ô tô đỏ ... trẻ sắp xếp các đồ theo màu sắc) (T)',NULL,2,1,'LD5013'),
 ('GL100063','VB.4.8','Ghép đôi được 25 đồ vật, tranh ảnh giống hệt nhau trong mảng lộn xộn 8 đối tượng có chứa 3 kích thích tương tự (vd: tìm chó trong 3 ảnh chó, mèo, gà, ngựa, dê, lợn) (T)',NULL,3,1,'LD5013'),
 ('GL100064','VB.4.9','Ghép đôi được 25 sự vật cùng loại không hoàn toàn giống nhau trong mảng lộn xộn 10 đối tượng chứa 3 kích thích tương tự (vd: Ghép xe tải ford với xe tải toyota) (T)',NULL,4,1,'LD5013'),
 ('GL100065','VB.4.10','Ghép 25 tranh ảnh với đồ vật không hoàn toàn giống nhau trong mảng lộn xộn 10 đối tượng có chứa 3 kích thích tương tự (vd: Ghép mô hình xe tải ford với ảnh xe tải toyota, có lẫn ảnh xe xúc, xe bus và 7 ảnh chủng loại khác) (T)',NULL,5,1,'LD5013'),
 ('GL100066','VB.5.6','Tìm kiếm đồ chơi hoặc một phần tương ứng của bộ đồ chơi bị thiếu cho 5 món đồ/bộ đồ chơi (vd: mảnh ghép, bóng để thả, bình sữa cho búp bê..) (E)',NULL,1,1,'LD5014'),
 ('GL100067','VB.5.7','Thể hiện độc lập việc sử dụng đồ chơi hoặc đồ vật theo chức năng của chúng đối với 5 món đồ (ví dụ: đặt tàu hỏa lên đường ray, kéo xe, áp điện thoại vào tai...) (O)',NULL,2,1,'LD5014'),
 ('GL100068','VB.5.8','Chơi với các vật dụng hàng ngày theo cách sáng tạo, 2 lần (ví dụ: dùng bát làm trống hoặc dùng hộp làm ô tô tưởng tượng) (O)',NULL,3,1,'LD5014'),
 ('GL100069','VB.5.9','Độc lập tham gia chơi trên các cấu trúc và thiết bị sân chơi trong tổng thời gian 5 phút (ví dụ: đi xuống cầu trướt, xích đu...) (TO 30 phút)',NULL,4,1,'LD5014'),
 ('GL100070','VB.5.10','Lắp ráp các đồ chơi có nhiều bộ phận cho 5 bộ vật liệu khác nhau (vd: Mr. Potato head, Little People sets, Cootie Bugs, ...) (O)',NULL,5,1,'LD5014'),
 ('GL100071','VB.6.7','Tự phát yêu cầu bạn cùng lứa 5 lần (ví dụ: Đến lượt tôi. Đẩy tôi. Nhìn này! Thôi nào!) (TO 60 phút)',NULL,1,1,'LD5015'),
 ('GL100072','VB.6.8','Tham gia vào trò chơi xã hội với bạn bè trong 3 phút mà không cần sự nhắc nhở hoặc khuyến khích của người lớn (ví dụ: hợp tác xếp một bộ đồ chơi, chơi nước) (TO 30 phút)',NULL,2,1,'LD5015'),
 ('GL100073','VB.6.9','Đáp ứng (trả lời) một cách tự nhiên trước yêu cầu của bạn bè 5 lần (ví dụ: Kéo tôi vào toa xe. Tôi muốn tàu.) (E)',NULL,3,1,'LD5015'),
 ('GL100074','VB.6.10','Tự phát ra lệnh cho các bạn cùng tham gia trò chơi, trò chơi giao lưu, v.v. 2 lần (ví dụ: Này các bạn. Hãy cùng đào một hố) (TO 60 phút)',NULL,4,1,'LD5015'),
 ('GL100075','VB.6.6','Bắt đầu tương tác thể chất với bạn bè 2 lần (ví dụ: đẩy xe, nắm tay, vòng quanh rosy) (TO 30 phút)',NULL,5,1,'LD5015'),
 ('GL100076','VB.7.6','Bắt chước 10 hành động yêu cầu chọn một đối tượng cụ thể từ một nhóm (ví dụ: chọn một dùi trống từ một nhóm cũng có chứa còi và chuông và bắt chước cách đánh trống của người lớn) (T)',NULL,1,1,'LD5016'),
 ('GL100077','VB.7.7','Bắt chước 20 hành động vận động tinh khác nhau khi được nhắc, Thực hiện điều này (ví dụ: ngọ nguậy ngón tay, nhéo, nắm tay, làm con bướm) (E)',NULL,2,1,'LD5016'),
 ('GL100078','VB.7.8','Bắt chước 10 chuỗi hành động gồm ba thành phần khác nhau khi được nhắc thực hiện điều này (ví dụ: vỗ tay, nhảy, chạm ngón chân; bế búp bê lên, đặt vào cũi và lắc lư nôi) (T)',NULL,3,1,'LD5016'),
 ('GL100079','VB.7.9','Tự động bắt chước 5 hành động chức năng trong môi trường tự nhiên (ví dụ: ăn bằng thìa, mặc áo khoác, cởi giày) (O)',NULL,4,1,'LD5016'),
 ('GL100080','VB.7.10','Bắt chước (hoặc cố gắng thực hiện một cách gần đúng) bất kỳ hành động vận động mới lạ nào do người lớn làm mẫu có và không có đồ vật (tức là một “tiết mục bắt chước tổng quát”) (T)',NULL,5,1,'LD5016'),
 ('GL100081','VB.8.6','Đạt ít nhất 50 điểm trong bài kiểm tra phụ EESA ( thêm ít nhất 20 từ nhóm 2) (T)',NULL,1,1,'LD5017'),
 ('GL100082','VB.8.7','Đạt ít nhất 60 điểm trong bài kiểm tra phụ EESA (thêm ít nhất 5 từ nhóm 3) (T)',NULL,2,1,'LD5017'),
 ('GL100083','VB.8.8','Đạt ít nhất 70 điểm trong bài kiểm tra phụ EESA (thêm ít nhất 15 từ nhóm 3) (T)',NULL,3,1,'LD5017'),
 ('GL100084','VB.8.9','Đạt ít nhất 80 điểm trong bài kiểm tra phụ EESA. (thêm ít nhất 25 từ nhóm 3) (T)',NULL,4,1,'LD5017'),
 ('GL100085','VB.8.10','Đạt ít nhất 90 điểm trong bài kiểm tra phụ EESA (ít nhất 10 từ nhóm 4 và 5) (T)',NULL,5,1,'LD5017'),
 ('GL100086','VB.10.6','Chọn 5 loại thực phẩm hoặc đồ uống khác nhau khi mỗi loại được trình bày thành mảng 5 món (với 4 món không phải đồ ăn hoặc đồ uống) và yêu cầu điền từ Con ăn… hay Con uống... (T)',NULL,1,1,'LD5018'),
 ('GL100087','VB.10.7','Chọn mục đúng từ một mảng gồm 8 mục cho 25 câu điền LRFFC khác nhau thuộc bất kỳ loại nào (ví dụ: Bạn ngồi trên một...- bối cảnh ghế lẫn vào trong 7 sự vật nữa) (T)',NULL,2,1,'LD5018'),
 ('GL100088','VB.10.8','Chọn mục đúng từ một mảng gồm 10 mục (hoặc từ một cuốn sách) cho 25 động từ-danh từ khác nhau, LRFFC của cái gì, cái nào, hoặc câu hỏi ai (ví dụ: Bạn đi xe gì? Con nào sủa? Ai có thể nhảy?) (T)',NULL,3,1,'LD5018'),
 ('GL100089','VB.10.9','Chọn một mục với 3 câu nói khác nhau về mỗi mục khi được trình bày độc lập (ví dụ: Tìm một con vật. Tiếng gì sủa? Gì có bàn chân?) cho 25 mục (T)',NULL,4,1,'LD5018'),
 ('GL100090','VB.10.10','Tự động chạm vào vật phẩm trong 50% số thử nghiệm LRFFC (ví dụ: Nó đang sủa/ Tìm một con vật và trong mảng có chứa hình ảnh của một con chó) (E)',NULL,5,1,'LD5018'),
 ('GL100091','VB.11.6','Hoàn thành 10 cụm từ điền vào chỗ trống khác nhau thuộc bất kỳ loại nào (ví dụ: điền vào bài hát, trò chơi xã hội và điền vào chỗ trống vui nhộn, âm thanh của động vật hoặc đồ vật) (T)',NULL,1,1,'LD5019'),
 ('GL100092','VB.11.7','Nói tên khi được hỏi: Tên bạn là gì? (T)',NULL,2,1,'LD5019'),
 ('GL100093','VB.11.8','Hoàn thành 25 cụm từ điền vào chỗ trống khác nhau, không bao gồm bài hát. (ví dụ: Con ăn... Con ngủ trên... Giày và...) (T)',NULL,3,1,'LD5019'),
 ('GL100094','VB.11.9','Trả lời 25 câu hỏi GÌ? khác nhau (vd: Bạn đánh răng bằng gì?...) (T)',NULL,4,1,'LD5019'),
 ('GL100095','VB.11.10','Trả lời 25 câu hỏi khác nhau về ai và ở đâu (ví dụ: Bạn của bạn là ai? Gối của bạn ở đâu?) (T)',NULL,5,1,'LD5019'),
 ('GL100096','VB.12.6','Ngồi tại bàn ăn nhẹ hoặc ăn trưa của nhóm mà không có hành vi tiêu cực trong 3 phút (O)',NULL,1,1,'LD5020'),
 ('GL100097','VB.12.7','Cất đồ dùng cá nhân, xếp hàng và đến bàn chỉ với 1 lời nhắc (O)',NULL,2,1,'LD5020'),
 ('GL100098','VB.12.8','Chuyển tiếp giữa các hoạt động trong lớp với không quá 1lần nhắc bằng cử chỉ hoặc lời nói (O)',NULL,3,1,'LD5020'),
 ('GL100099','VB.12.9','Ngồi trong một nhóm nhỏ từ 3 trẻ trở lên trong 5 phút mà không có hành vi gây rối hoặc cố gắng rời khỏi nhóm (O)',NULL,4,1,'LD5020'),
 ('GL100100','VB.12.10','Ngồi trong một nhóm nhỏ từ 3 trẻ trở lên trong 10 phút, chú ý đến giáo viên hoặc tài liệu trong 50% thời gian và phản ứng với 5 kích thích từ giáo viên (O)',NULL,5,1,'LD5020');
INSERT INTO goals (id,code,name,description,display_order,is_active,level_domain_id) VALUES
 ('GL100101','VB.13.7','Có vốn từ vựng dành cho người nghe là 100 từ (ví dụ: Chạm mũi. Nhảy. Tìm chìa khóa.) (T)',NULL,1,1,'LD5021'),
 ('GL100102','VB.13.8','Hàng ngày, nói 10 cụm/câu có cấu trúc gồm 2 thành phần khác nhau thuộc bất kỳ loại chức năng nào ngoại trừ phát âm (ví dụ: yêu cầu, gán tên) (E)',NULL,2,1,'LD5021'),
 ('GL100103','VB.13.9','Phát ra âm điệu chức năng (nhịp điệu, trọng âm, ngữ điệu) 5 lần trong một ngày (ví dụ, nói có nhịp điệu hoặc nhấn mạnh trọng âm vào một số từ nhất định ở những thời điểm thích hợp như: Đó là CỦA CON!) (O)',NULL,3,1,'LD5021'),
 ('GL100104','VB.13.10','Vốn từ vựng của người nói là 300 từ (tất cả các dạng hoạt động của ngôn từ ngoại trừ phát âm) (E)',NULL,4,1,'LD5021'),
 ('GL100105','VB.13.6','Người lớn thân quen hiểu được 10 phát âm của trẻ khi trẻ gán tên các sự vật họ không cần nhìn thấy (T)',NULL,5,1,'LD5021'),
 ('GL100106','VB.1.11','5 lần tự phát yêu cầu thông tin bằng sử dụng từ để hỏi Gì? Ai? Ở đâu? vd: Bạn tên gì? Tôi cần đi đâu? (TO 60 phút)',NULL,1,1,'LD5022'),
 ('GL100107','VB.1.12','Lịch sự yêu cầu dừng một hoạt động không mong muốn/tác nhân gây khó chịu trong 5 trường hợp khác nhau (vd: Đừng đẩy tớ; Xin lỗi, mình không thích) (E)',NULL,2,1,'LD5022'),
 ('GL100108','VB.1.13','Đưa ra yêu cầu với 10 tính từ, giới từ hoặc trạng từ khác nhau (vd: Lấy nó ra, Đi nhanh lên, Cắt thẳng ) (TO 60 phút)',NULL,3,1,'LD5022'),
 ('GL100109','VB.1.14','Đưa ra 5 chỉ dẫn, hướng dẫn hoặc giải thích cho người khác làm điều gì đó hoặc hành động thế nào (vd: Bạn bôi keo vào trước, rồi mới dán. Bạn ngồi đây trong lúc tớ lấy sách) (O)',NULL,4,1,'LD5022'),
 ('GL100110','VB.1.15','Yêu cầu người khác chú ý tới hành vi hội thoại của mình 5 lần (vd: Nghe tôi nói ... , Hãy để tôi kể cho ... , Chuyện như thế này ....) (O)',NULL,5,1,'LD5022'),
 ('GL100111','VB.2.11','Gán tên màu sắc, hình dạng, chức năng của 5 đồ vật (đồ vật và câu hỏi được đưa ra hỗn hợp, vd: con dùng bóng làm gì, bông hoa màu gì, tủ lạnh hình dạng gì?) (T)',NULL,1,1,'LD5023'),
 ('GL100112','VB.2.12','Nói được 4 giới từ (trong, ngoài, trên, dưới) và 4 đại từ (tôi, bạn...) (E)',NULL,2,1,'LD5023'),
 ('GL100113','VB.2.13','Nói được 4 tính từ không bao gồm màu sắc, hình dạng ( vd: lớn, nhỏ, dài, ngắn) và 4 trạng từ (vd: nhanh, chậm, lặng lẽ, nhẹ nhàng) (E)',NULL,3,1,'LD5023'),
 ('GL100114','VB.2.14','Sử dụng câu hoàn chỉnh 4 từ, 20 lần (E)',NULL,4,1,'LD5023'),
 ('GL100115','VB.2.15','Có vốn từ vựng đạt 1000 từ (danh từ, động từ, tính từ ...) được kiểm tra từ danh sách tích lũy và các bài tập đã thực hiện (T)',NULL,5,1,'LD5023'),
 ('GL100116','VB.3.11','Tự sao chép được mẫu của 2 hoạt động thủ công/nghệ thuật (vd: nhìn mẫu quả bóng đỏ của bạn khác, biết tô màu đỏ vào quả bóng của mình) (O)',NULL,1,1,'LD5024'),
 ('GL100117','VB.3.12','Thể hiện khả năng khái quát hóa bằng ghép đôi các đối tượng mới không hoàn toàn giống nhau ngay trong lần thử đầu tiên, đạt 25 sự vật trong mảng lộn xộn 10 đối tượng có chứa 3 kích thích tương tự (T)',NULL,2,1,'LD5024'),
 ('GL100118','VB.3.13','Hoàn thành được 20 thiết kế khối hoặc dạng lát gỗ khác nhau từ 8 mảnh khác nhau (T)',NULL,3,1,'LD5024'),
 ('GL100119','VB.3.14','Phân loại 5 nhóm, mỗi nhóm 5 sự vật mà không cần mô hình mẫu (vd: động vật, quần áo, đồ nội thất ...) (T)',NULL,4,1,'LD5024'),
 ('GL100120','VB.3.15','Điền tiếp vào quy luật 3 bước ở 20 mẫu (vd: ê¨⌂ê¨…) mẫu tăng độ khó từ hình dạng, hình ảnh vật, hình thật (T)',NULL,5,1,'LD5024'),
 ('GL100121','VB.4.11','Tự sao chép được mẫu của 2 hoạt động thủ công/nghệ thuật (vd: nhìn mẫu quả bóng đỏ của bạn khác, biết tô màu đỏ vào quả bóng của mình) (O)',NULL,1,1,'LD5025'),
 ('GL100122','VB.4.12','Thể hiện khả năng khái quát hóa bằng ghép đôi các đối tượng mới không hoàn toàn giống nhau ngay trong lần thử đầu tiên, đạt 25 sự vật trong mảng lộn xộn 10 đối tượng có chứa 3 kích thích tương tự (T)',NULL,2,1,'LD5025'),
 ('GL100123','VB.4.13','Hoàn thành được 20 thiết kế khối hoặc dạng lát gỗ khác nhau từ 8 mảnh khác nhau (T)',NULL,3,1,'LD5025'),
 ('GL100124','VB.4.14','Phân loại 5 nhóm, mỗi nhóm 5 sự vật mà không cần mô hình mẫu (vd: động vật, quần áo, đồ nội thất ...) (T)',NULL,4,1,'LD5025'),
 ('GL100125','VB.4.15','Điền tiếp vào quy luật 3 bước ở 20 mẫu (vd: ê¨⌂ê¨…) mẫu tăng độ khó từ hình dạng, hình ảnh vật, hình thật (T)',NULL,5,1,'LD5025'),
 ('GL100126','VB.5.11','Tự phát tham gia vào trò chơi giả vờ hoặc tưởng tượng trong 5 lần (ví dụ: mặc quần áo hóa trang, một bữa tiệc giả vờ với thú bông, giả vờ nấu ăn) (O)',NULL,1,1,'LD5026'),
 ('GL100127','VB.5.12','Lặp lại hành vi vận động thô để đạt được hiệu quả tốt hơn cho 2 hoạt động (ví dụ: ném bóng vào rổ, vung vợt đánh bóng chữ T, dậm chân để phóng tên lửa, vung vợt) (O)',NULL,2,1,'LD5026'),
 ('GL100128','VB.5.13','Độc lập tham gia vào các hoạt động nghệ thuật và thủ công trong 5 phút (ví dụ: vẽ, tô màu, tô màu, cắt, dán) (O)',NULL,3,1,'LD5026'),
 ('GL100129','VB.5.14','Tham gia một cách độc lập vào các hoạt động vui chơi kéo dài trong 10 phút mà không cần người lớn nhắc nhở hoặc khuyến khích (ví dụ: chơi trò chơi hóa trang) (O)',NULL,4,1,'LD5026'),
 ('GL100130','VB.5.15','Độc lập vẽ hoặc viết vào sách hoạt động tiền học đường trong 5 phút (ví dụ: trò chơi nối điểm, trò chơi nối điểm, mê cung, truy tìm chữ cái và số) (O)',NULL,5,1,'LD5026'),
 ('GL100131','VB.6.11','Hợp tác tự phát với bạn cùng lứa để hoàn thành được một kết quả cụ thể 5 lần (ví dụ: một trẻ cầm một cái xô trong khi trẻ kia đổ nước) (E)',NULL,1,1,'LD5027'),
 ('GL100132','VB.6.12','Tự phát ra lệnh cho bạn cùng lứa bằng câu hỏi Ai? Gi? Ở đâu? 5 lần (ví dụ: Bạn đang đi đâu? Cái gì vậy? Bạn là ai) (TO 60 phút)',NULL,2,1,'LD5027'),
 ('GL100133','VB.6.13','Trả lời bằng lời nói cho 5 câu hỏi hoặc câu nói khác nhau từ bạn bè (ví dụ: trả lời bằng lời nói Bạn muốn chơi gì?) (E)',NULL,3,1,'LD5027'),
 ('GL100134','VB.6.14','Tham gia vào các hoạt động chơi xã hội giả vờ với bạn bè trong 5 phút mà không cần sự nhắc nhở hoặc khuyến khích của người lớn (ví dụ: chơi hóa trang, diễn xuất trong video, chơi gia đình) (O)',NULL,4,1,'LD5027'),
 ('GL100135','VB.6.15','Tham gia 4 hội thoại bằng lời về 1 chủ đề với các bạn trong 5 chủ đề (ví dụ: trẻ trao đổi qua lại nói về việc tạo một con lạch trong hộp cát) (O)',NULL,5,1,'LD5027'),
 ('GL100136','VB.10.11','Chọn đúng mục từ một mảng gồm 10 mục chứa 3 kích thích tương tự nhau (ví dụ: màu sắc, hình dạng hoặc nhóm tương nhau), cho 25 nhiệm vụ LRFFC với câu hỏi WH khác nhau (T)',NULL,1,1,'LD5028'),
 ('GL100137','VB.10.12','Chọn một mục từ một cuốn sách dựa trên 2 thành phần từ ngữ: là một đặc điểm (ví dụ: màu sắc), chức năng (ví dụ: vẽ bằng) hoặc chủng loại (ví dụ: quần áo) cho 25 mục (ví dụ: Bạn có thấy một con vật màu nâu không? Bạn có thể tìm thấy vài thứ quần áo có nút không?) (T)',NULL,2,1,'LD5028'),
 ('GL100138','VB.10.13','Chọn các mục từ một cuốn sách hoặc trong môi trường tự nhiên dựa trên 3 thành phần từ ngữ (ví dụ: động từ, tính từ, giới từ, đại từ), cho 25 nhiệm vụ LRFFC có dạng câu hỏi WH (ví dụ: Quả nào mọc trên cây?, Con bò nào được vắt sữa?) (T)',NULL,3,1,'LD5028'),
 ('GL100139','VB.10.14','Chọn các mục chính xác từ một cuốn sách hoặc môi trường tự nhiên với 4 câu hỏi LRFFC luân phiên khác nhau về một chủ đề duy nhất (Con bò sống ở đâu? Con bò ăn gì? Ai vắt sữa bò?...) cho 25 chủ đề khác nhau (T)',NULL,4,1,'LD5028'),
 ('GL100140','VB.10.15','Thể hiện 1000 phản hồi LRFFC khác nhau, được kiểm tra hoặc thu thập từ danh sách tích lũy các phản hồi đã biết. (Chọn một mục từ mảng 10 mục liên quan) Chú thích: Ghi lại các LRFFC trên một bảng theo dõi kỹ năng riêng biệt và ghi ngày dưới tổng số khi chúng được hoàn thành, giữ LRFFC được ghi lại trong sổ chương trình của học sinh để tham khảo) (T)',NULL,5,1,'LD5028'),
 ('GL100141','VB.11.11','Tự phát ra 20 hội thoại bằng lời nói (có thể là một yêu cầu) (ví dụ: bố nói Bố sẽ đi ô tô, và đứa trẻ tự phát nói "con muốn đi xe cùng" (O)',NULL,1,1,'LD5029'),
 ('GL100142','VB.11.12','Thể hiện 300 phản hồi hội thoại khác nhau, được thử nghiệm hoặc thu được từ danh sách tích lũy các hội thoại đã biết (T)',NULL,2,1,'LD5029'),
 ('GL100143','VB.11.13','Trả lời 2 câu hỏi sau khi được đọc cho một đoạn văn ngắn (15+ từ) trong sách, cho 25 đoạn văn (ví dụ: Ai đã thổi bay ngôi nhà?) (T)',NULL,3,1,'LD5029'),
 ('GL100144','VB.11.14','Mô tả 25 sự kiện, video, câu chuyện khác nhau, v.v. bằng hơn 8 từ (ví dụ: Hãy kể cho cô biết chuyện gì đã xảy ra… Con quái vật lớn làm mọi người sợ hãi và tất cả đều chạy vào nhà) có thể theo cả 2 cách Phản hồi hoặc Tự phát (E)',NULL,4,1,'LD5029'),
 ('GL100145','VB.11.15','Trả lời 4 câu hỏi xoay vòng dạng Gì? Ai? Ở đâu? khác nhau về một chủ đề trong 10 chủ đề (ví dụ: Ai đưa bạn đến trường? Bạn đi học ở đâu? Bạn mang gì đến trường? Cái gì chở bạn đi học?) (T)',NULL,5,1,'LD5029'),
 ('GL100146','VB.12.11','Sử dụng nhà vệ sinh và rửa tay khi được nhắc chỉ bằng lời (E)',NULL,1,1,'LD5030'),
 ('GL100147','VB.12.12','Phản hồi với 5 hướng dẫn hoặc câu hỏi nhóm khác nhau mà không có lời nhắc trực tiếp trong nhóm từ 3 trẻ trở lên (ví dụ: Tất cả đứng lên! hoặc "có ai mặc áo đỏ không?") (O)',NULL,2,1,'LD5030'),
 ('GL100148','VB.12.13','Hoạt động độc lập 5 phút trong nhóm từ 3 trẻ trờ lên và duy trì nhiệm vụ trong 50 % thời gian. (O)',NULL,3,1,'LD5030'),
 ('GL100149','VB.12.14','Có được 2 hành vi mới trong hình thức dạy học nhóm kéo dài 15 phút với nhóm từ 5 trẻ trở lên (T)',NULL,4,1,'LD5030'),
 ('GL100150','VB.12.15','Ngồi học nhóm từ 5 trẻ trở lên kéo dài 20 phút mà không có hành vi gây rối và trả lời được 5 câu hỏi hội thoại (T)',NULL,5,1,'LD5030'),
 ('GL100151','VB.13.11','Nói được các biến tố danh từ bằng cách kết hợp 10 danh từ gốc làm hậu tố cho danh từ số nhiều (ví dụ: chó so với nhiều chó) và 10 danh từ gốc làm hậu tố cho danh từ sở hữu (ví dụ: vòng cổ của chó và vòng cổ của mèo) (E)',NULL,1,1,'LD5031'),
 ('GL100152','VB.13.12','Nói được các biến tố động từ bằng cách kết hợp 10 động từ gốc làm hậu tố cho thì quá khứ thông thường (ví dụ: đã chơi) và 10 động từ gốc làm hậu tố cho thì tương lai (ví dụ: sẽ chơi) (E)',NULL,2,1,'LD5031'),
 ('GL100153','VB.13.13','Nói được 10 cụm danh từ khác nhau chứa ít nhất 3 từ với 2 bổ ngữ (ví dụ: tính từ, giới từ, đại từ) (ví dụ: Anh ấy là con rối của tôi. Kem sô cô la trong cốc) (E)',NULL,3,1,'LD5031'),
 ('GL100154','VB.13.14','Nói được 10 cụm động từ khác nhau chứa ít nhất 3 từ với 2 bổ ngữ (ví dụ: trạng từ, giới từ, đại từ) (ví dụ: Đẩy tôi mạnh lên. Đi xuống bậc thang.) (E)',NULL,4,1,'LD5031'),
 ('GL100155','VB.13.15','Kết hợp các cụm danh từ và động từ để tạo ra 10 mệnh đề hoặc câu khác nhau đúng cú pháp chứa ít nhất 5 từ (ví dụ: Con chó đốm liếm vào mặt tôi, Hoa cúc vàng nở rộ trong vườn) (E)',NULL,5,1,'LD5031'),
 ('GL100156','VB.14.11','Trẻ tập trung vào một cuốn sách khi đang được đọc cho trẻ nghe trong 75% thời gian mà không cần lời nhắc (TO 3 phút)',NULL,1,1,'LD5032'),
 ('GL100157','VB.14.12','Chọn chữ in hoa chính xác từ một mảng 5 chữ cái, cho 10 chữ cái khác nhau (T)',NULL,2,1,'LD5032'),
 ('GL100158','VB.14.13','Đọc 10 chữ in hoa theo yêu cầu từ bảng chữ cái (T)',NULL,3,1,'LD5032'),
 ('GL100159','VB.14.14','Đọc tên của mình (T)',NULL,4,1,'LD5032'),
 ('GL100160','VB.14.15','Nối 5 từ với các hình ảnh hoặc vật tương ứng trong mảng 5 và ngược lại (ví dụ: ghép từ viết chim với hình ảnh một con chim) (T)',NULL,5,1,'LD5032'),
 ('GL100161','VB.15.11','Bắt chước 5 hành động viết khác nhau do người lớn làm mẫu bằng cách sử dụng dụng cụ viết (bút chì, sáp) và bề mặt viết (giấy, bảng) (vd: tay thuận, nghuệch ngoạc, thẳng, cong, chéo, vòng tròn to nhỏ ...) (T)',NULL,1,1,'LD5033'),
 ('GL100162','VB.15.12','Tự mình vẽ các đường có độ dài ¼ inch (0.64cm) của 5 hình dạng hình học khác nhau (ví dụ: hình tròn, hình vuông, hình tam giác, hình chữ nhật, hình ngôi sao) (T)',NULL,2,1,'LD5033'),
 ('GL100163','VB.15.14','Đánh vần chữ cái và viết rõ ràng tên của chính mình mà không cần sao chép (T)',NULL,3,1,'LD5033'),
 ('GL100164','VB.15.15','Sao chép tất cả chữ cái viết hoa và viết thường trong bảng chữ cái một cách rõ ràng (T)',NULL,4,1,'LD5033'),
 ('GL100165','VB.15.13','Sao chép rõ ràng 10 chữ cái hoặc số (T)',NULL,5,1,'LD5033'),
 ('GL100166','VB.16.11','Nghe hiểu các số từ 1-5 trong một mảng gồm 5 số khác nhau (T)',NULL,1,1,'LD5034'),
 ('GL100167','VB.16.12','Gọi tên các số 1-5 (T)',NULL,2,1,'LD5034'),
 ('GL100168','VB.16.13','Đếm/lấy ra 1-5 vật phẩm từ một tập hợp nhiều hơn các vật phẩm với tỷ lệ tương ứng 1-1 (ví dụ: Cho tôi 4 ô tô. Bây giờ cho tôi 2 ô tô.) (T)',NULL,3,1,'LD5034'),
 ('GL100169','VB.16.14','Nghe hiểu xác định được 8 phép so sánh khác nhau liên quan đến đo lường (ví dụ: chỉ cho tôi nhiều hay ít, lớn hay nhỏ, dài hay ngắn, đầy hay rỗng, ồn ào hay yên tĩnh) (T)',NULL,4,1,'LD5034'),
 ('GL100170','VB.16.15','Ghép đúng số với số lượng và số lượng với số phạm vi từ 1-5 (ví dụ: ghép số 3 với hình ảnh 3 chiếc xe tải) (T)',NULL,5,1,'LD5034');
